def solve(grid):
    from collections import Counter

    # find the shape color (most frequent non‑zero value)
    cnt = Counter()
    for row in grid:
        for v in row:
            if v != 0:
                cnt[v] += 1
    if not cnt:
        return []
    shape_color = max(cnt, key=cnt.get)

    # locate the numeric region (all cells that are non‑zero and not the shape color)
    num_min_r = num_max_r = num_min_c = num_max_c = None
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v != 0 and v != shape_color:
                if num_min_r is None:
                    num_min_r = num_max_r = i
                    num_min_c = num_max_c = j
                else:
                    if i < num_min_r: num_min_r = i
                    if i > num_max_r: num_max_r = i
                    if j < num_min_c: num_min_c = j
                    if j > num_max_c: num_max_c = j

    nr = num_max_r - num_min_r + 1
    nc = num_max_c - num_min_c + 1
    numeric_grid = [[grid[i][j] for j in range(num_min_c, num_max_c + 1)]
                    for i in range(num_min_r, num_max_r + 1)]

    # bounding box of the shape
    shape_min_r = shape_max_r = shape_min_c = shape_max_c = None
    for i, row in enumerate(grid):
        for j, v in enumerate(row):
            if v == shape_color:
                if shape_min_r is None:
                    shape_min_r = shape_max_r = i
                    shape_min_c = shape_max_c = j
                else:
                    if i < shape_min_r: shape_min_r = i
                    if i > shape_max_r: shape_max_r = i
                    if j < shape_min_c: shape_min_c = j
                    if j > shape_max_c: shape_max_c = j

    shape_h = shape_max_r - shape_min_r + 1
    shape_w = shape_max_c - shape_min_c + 1

    block_h = shape_h // nr
    block_w = shape_w // nc

    # build mask: True where a block is completely filled with the shape color
    mask = [[False] * nc for _ in range(nr)]
    for i in range(nr):
        for j in range(nc):
            r0 = shape_min_r + i * block_h
            r1 = r0 + block_h
            c0 = shape_min_c + j * block_w
            c1 = c0 + block_w
            all_shape = True
            for rr in range(r0, r1):
                for cc in range(c0, c1):
                    if grid[rr][cc] != shape_color:
                        all_shape = False
                        break
                if not all_shape:
                    break
            mask[i][j] = all_shape

    # produce output grid
    output = [[0] * nc for _ in range(nr)]
    for i in range(nr):
        for j in range(nc):
            if mask[i][j]:
                output[i][j] = numeric_grid[i][j]
    return output

